"""审批演示库的异常体系。

所有异常都继承 ApprovalError，便于调用方统一兜底；
规则判定失败与状态机失败分开，方便区分"业务不允许"和"参数不合法"。
"""


class ApprovalError(Exception):
    """所有业务异常的基类。"""


class AmountError(ApprovalError, ValueError):
    """金额非法：空值、非数字、超过两位小数、非正数、使用了浮点数。"""


class NotFoundError(ApprovalError):
    """申请单不存在。"""


class IdempotencyConflict(ApprovalError):
    """提交编号已被占用，且本次提交内容与已有内容不一致。"""

    def __init__(self, submit_id: str, detail: str):
        self.submit_id = submit_id
        self.detail = detail
        super().__init__(f"提交编号 {submit_id} 已存在且内容不同：{detail}")


class InvalidState(ApprovalError):
    """当前状态不允许该操作，例如撤回后继续审批、已批准再审批。"""


class SelfApprovalError(ApprovalError):
    """申请人试图审批自己的申请。"""


class NotAssignee(ApprovalError):
    """操作人不是当前审批节点的审批人。"""


class NotApplicant(ApprovalError):
    """只有申请人本人可以撤回。"""


class BudgetInsufficient(ApprovalError):
    """最终批准时部门可用预算不足。"""


class VersionConflict(ApprovalError):
    """乐观锁版本不一致，说明单据已被他人改动。"""
PYEOF
cat > proj/approval_demo/money.py <<'PYEOF'
"""金额工具：一律以整数"分"存储与比较，禁止浮点参与判断。

设计要点
--------
1. 入参只接受 str / Decimal / 整数分（通过 from_cents 显式传）；
2. 传入 float 直接报错，而不是"顺手转一下"，避免 0.1+0.2 类误差进入规则；
3. 超过两位小数直接拒绝，不做静默四舍五入；
4. 对外展示统一走 format_cents，保证与内部整数一一对应。
"""

from decimal import Decimal, InvalidOperation

from .errors import AmountError

_CENT = Decimal("0.01")
_CENT_FACTOR = 100


def parse_amount(value) -> int:
    """把用户输入的"元"解析成整数分。

    支持：str（如 "8000.01"）、Decimal("8000.01")。
    拒绝：float、bool、int（整数含义不明确，请用 from_cents）、空值、非正数、超过两位小数。
    """
    if isinstance(value, bool) or isinstance(value, float):
        raise AmountError("金额不允许使用浮点数，请传字符串或 Decimal，例如 '8000.01'")
    if isinstance(value, int):
        raise AmountError("整数的单位不明确，请用 from_cents(800001) 表示分，或用字符串表示元")

    if isinstance(value, Decimal):
        amount = value
    elif isinstance(value, str):
        text = value.strip().replace(",", "")
        if not text:
            raise AmountError("金额不能为空")
        try:
            amount = Decimal(text)
        except InvalidOperation as exc:
            raise AmountError(f"金额格式非法：{value!r}") from exc
    else:
        raise AmountError(f"金额类型不支持：{type(value).__name__}")

    if not amount.is_finite():
        raise AmountError("金额必须是有限数值")
    try:
        quantized = amount.quantize(_CENT)
    except InvalidOperation as exc:
        raise AmountError(f"金额精度超出可表示范围：{value!r}") from exc
    if quantized != amount:
        raise AmountError(f"金额最多两位小数，收到 {value!r}")

    cents = int(amount * _CENT_FACTOR)
    if cents <= 0:
        raise AmountError("金额必须大于 0")
    return cents


def from_cents(cents: int) -> int:
    """显式以"分"为单位构造金额。"""
    if isinstance(cents, bool) or not isinstance(cents, int):
        raise AmountError("from_cents 只接受整数分")
    if cents <= 0:
        raise AmountError("金额必须大于 0")
    return cents


def format_cents(cents: int) -> str:
    """把整数分格式化成两位小数的元，用于展示与日志。"""
    if not isinstance(cents, int) or isinstance(cents, bool):
        raise AmountError("format_cents 只接受整数分")
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}{cents // 100}.{cents % 100:02d}"
