from approval_demo import *

def svc(total='100000.00'):
    repo = InMemoryRepository({'D100': Budget('D100', parse_amount(total))})
    d = ApproverDirectory({'L1':'U-SUP','L2':'U-FIN','L3':'U-HEAD'})
    return ApprovalService(repo, d), repo

s, r = svc()
# 申请人就是财务，金额跨越 8000，需走财务节点
rid = s.submit('X1', 'U-FIN', 'D100', '20000').request.request_id
s.approve(rid, 'U-SUP')
try:
    s.approve(rid, 'U-FIN')
    print('BUG: 财务自审通过')
except SelfApprovalError:
    print('ok 财务自审被拒')
except Exception as e:
    print('其他异常', type(e).__name__, e)

# 申请人就是负责人
s2, _ = svc()
rid2 = s2.submit('X2', 'U-HEAD', 'D100', '40000').request.request_id
s2.approve(rid2, 'U-SUP'); s2.approve(rid2, 'U-FIN')
try:
    s2.approve(rid2, 'U-HEAD'); print('BUG: 负责人自审通过')
except SelfApprovalError: print('ok 负责人自审被拒')

# 空申请人/空部门
s3, _ = svc()
for kwargs in [dict(applicant_id='', dept_id='D100'), dict(applicant_id='U-APP', dept_id='')]:
    try:
        s3.submit('X3', kwargs['applicant_id'], kwargs['dept_id'], '100')
        print('BUG: 空字段被接受', kwargs)
