{"command": "mkdir -p proj/approval_demo proj/tests proj/docs && cat > proj/approval_demo/errors.py <<'PYEOF'
"""审批演示库的异常体系。

所有异常都继承 ApprovalError，便于调用方统一兜底；
规则判定失败与状态机失败分开，方便区分"业务不允许"和"参数不合法"。
"""


class ApprovalError(Exception):
    """所有业务异常的基类。"""


class AmountError(ApprovalError, ValueError):
    """金额非法：空值、非数字、超过两位小数、非正数、使用了浮点数。"""


class NotFoundError(ApprovalError):
    """申请单不存在。"""


class IdempotencyConflict(ApprovalError):
    """提交编号已被占用，且本次提交内容与已有内容不一致。"""

    def __init__(self, submit_id: str, detail: str):
        self.submit_id = submit_id
        self.detail = detail
        super().__init__(f"提交编号 {submit_id} 已存在且内容不同：{detail}")


class InvalidState(ApprovalError):
    """当前状态不允许该操作，例如撤回后继续审批、已批准再审批。"""


class SelfApprovalError(ApprovalError):
    """申请人试图审批自己的申请。"""


class NotAssignee(ApprovalError):
    """操作人不是当前审批节点的审批人。"""


class NotApplicant(ApprovalError):
    """只有申请人本人可以撤回。"""


class BudgetInsufficient(ApprovalError):
    """最终批准时部门可用预算不足。"""


class VersionConflict(ApprovalError):
