_CENT_FACTOR = 100


def parse_amount(value) -> int:
    """把用户输入的"元"解析成整数分。

    支持：str（如 "8000.01"）、Decimal("8000.01")。
    拒绝：float、bool、int（整数含义不明确，请用 from_cents）、空值、非正数、超过两位小数。
    """
    if isinstance(value, bool) or isinstance(value, float):
        raise AmountError("金额不允许使用浮点数，请传字符串或 Decimal，例如 '8000.01'")
    if isinstance(value, int):
        raise AmountError("整数的单位不明确，请用 from_cents(800001) 表示分，或用字符串表示元")

    if isinstance(value, Decimal):
        amount = value
    elif isinstance(value, str):
        text = value.strip().replace(",", "")
        if not text:
            raise AmountError("金额不能为空")
        try:
            amount = Decimal(text)
        except InvalidOperation as exc:
            raise AmountError(f"金额格式非法：{value!r}") from exc
    else:
        raise AmountError(f"金额类型不支持：{type(value).__name__}")

    if not amount.is_finite():
        raise AmountError("金额必须是有限数值")
    try:
        quantized = amount.quantize(_CENT)
    except InvalidOperation as exc:
        raise AmountError(f"金额精度超出可表示范围：{value!r}") from exc
    if quantized != amount:
        raise AmountError(f"金额最多两位小数，收到 {value!r}")

    cents = int(amount * _CENT_FACTOR)
    if cents <= 0:
        raise AmountError("金额必须大于 0")
    return cents


def from_cents(cents: int) -> int:
    """显式以"分"为单位构造金额。"""
    if isinstance(cents, bool) or not isinstance(cents, int):
        raise AmountError("from_cents 只接受整数分")
    if cents <= 0:
        raise AmountError("金额必须大于 0")
    return cents


def format_cents(cents: int) -> str:
    """把整数分格式化成两位小数的元，用于展示与日志。"""
    if not isinstance(cents, int) or isinstance(cents, bool):
        raise AmountError("format_cents 只接受整数分")
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}{cents // 100}.{cents % 100:02d}"
