"""规则层：只做判断，不碰存储、不碰状态改写。

规则层的三个约定
----------------
1. 全部入参都是整数分或纯数据对象，函数无副作用、可重复求值；
2. 每个函数返回 RuleHit（规则号 + 是否通过 + 人话说明），
   引擎把这些命中结果原样写进决策记录，这就是"可解释"的全部来源；
3. 阈值只在本文件出现一次，改规则改这里，不需要翻业务代码。
"""

from dataclasses import dataclass
from typing import Dict, Tuple

from .model import NODE_LABEL, Budget, Request, RuleHit, Status
from .money import format_cents

# 新规则集版本号：规则变更必须改这个号，历史决策据此回溯
RULE_SET_VERSION = "APR-27B/rs-v2"

# 分级阈值（整数分）。只在这里定义，别处一律引用常量。
TIER1_MAX_CENTS = 800_000     # 8000.00 元
TIER2_MAX_CENTS = 3_000_000   # 30000.00 元


@dataclass(frozen=True)
class Tier:
    """分级结果：命中哪条规则、区间怎么写、审批链是什么。"""

    rule: str
    interval: str
    chain: Tuple[str, ...]

    @property
    def chain_labels(self) -> Tuple[str, ...]:
        return tuple(NODE_LABEL[node] for node in self.chain)


def tier_for(amount_cents: int) -> Tier:
    """按金额（整数分）计算审批链。

    区间口径（左开右闭，边界只归属一侧）：
        0.01 ~ 8000.00      -> 主管
        8000.01 ~ 30000.00  -> 主管 + 财务
        30000.01 以上       -> 主管 + 财务 + 负责人
    """
    if amount_cents <= TIER1_MAX_CENTS:
        return Tier(
            rule="R-TIER-1",
            interval=f"[0.01, {format_cents(TIER1_MAX_CENTS)}]",
            chain=("L1",),
        )
    if amount_cents <= TIER2_MAX_CENTS:
        return Tier(
            rule="R-TIER-2",
            interval=f"({format_cents(TIER1_MAX_CENTS)}, {format_cents(TIER2_MAX_CENTS)}]",
            chain=("L1", "L2"),
        )
    return Tier(
        rule="R-TIER-3",
        interval=f"({format_cents(TIER2_MAX_CENTS)}, +inf)",
        chain=("L1", "L2", "L3"),
    )


def check_amount(amount_cents: int) -> RuleHit:
    """R-AMOUNT：金额必须是正整数分。解析阶段已拦一次，这里再兜一次底。"""
    ok = isinstance(amount_cents, int) and not isinstance(amount_cents, bool) and amount_cents > 0
    detail = (
        f"金额 {format_cents(amount_cents)} 元（{amount_cents} 分）合法"
        if ok
        else "金额必须为正整数分"
    )
    return RuleHit("R-AMOUNT", ok, detail)


def check_budget(budget: Budget, amount_cents: int) -> RuleHit:
    """R-BUDGET：最终批准时校验可用预算。注意这里不预占，只看余额够不够。"""
    ok = budget.available_cents >= amount_cents
    detail = (
        f"部门 {budget.dept_id} 可用 {format_cents(budget.available_cents)} 元，"
        f"申请 {format_cents(amount_cents)} 元，"
        + ("预算充足" if ok else "预算不足")
    )
    return RuleHit("R-BUDGET", ok, detail)


def check_self_approval(applicant_id: str, actor_id: str) -> RuleHit:
    """R-SOD：申请人不能审批自己的申请。"""
    ok = applicant_id != actor_id
    detail = (
        f"审批人 {actor_id} 与申请人 {applicant_id} 不同，满足职责分离"
        if ok
        else f"审批人 {actor_id} 就是申请人本人，禁止自审"
    )
    return RuleHit("R-SOD", ok, detail)


def check_assignee(expected_approver_id: str, actor_id: str) -> RuleHit:
    """R-ASSIGNEE：只有当前节点的审批人可以操作。"""
    ok = expected_approver_id == actor_id
    detail = (
        f"操作人 {actor_id} 是当前节点审批人"
        if ok
        else f"操作人 {actor_id} 不是当前节点审批人（应为 {expected_approver_id}）"
    )
    return RuleHit("R-ASSIGNEE", ok, detail)


def check_pending(request: Request) -> RuleHit:
    """R-STATE：只有待审批状态可以审批或撤回。"""
    ok = request.status is Status.PENDING
    detail = (
        f"{request.request_id} 当前状态 {request.status.value}，允许操作"
        if ok
        else f"{request.request_id} 当前状态 {request.status.value}，已结束，不允许操作"
    )
    return RuleHit("R-STATE", ok, detail)


def explain_chain(chain: Tuple[str, ...]) -> Dict[str, object]:
    """把审批链翻译成可读结构，供决策记录与示例输出使用。"""
    return {
        "chain": list(chain),
        "labels": [NODE_LABEL[node] for node in chain],
        "length": len(chain),
    }
