    def audit(self) -> List[str]:
        """一致性自查：返回问题列表（空表示通过）。"""
        problems: List[str] = []
        ledger = self._repo.ledger()
        debited = {}
        for entry in ledger:
            debited.setdefault(entry.request_id, []).append(entry)

        for request in self._repo.all_requests():
            entries = debited.get(request.request_id, [])
            if request.status is Status.APPROVED:
                if len(entries) != 1:
                    problems.append(f"{request.request_id} 已批准但扣减流水 {len(entries)} 条（应为 1）")
                elif entries[0].amount_cents != request.amount_cents:
                    problems.append(f"{request.request_id} 扣减金额 {entries[0].amount_cents} 与申请金额 {request.amount_cents} 不一致")
            else:
                if entries:
                    problems.append(f"{request.request_id} 状态 {request.status.value} 却有扣减流水")
            if request.status is Status.PENDING and not (0 <= request.node_index < len(request.chain)):
                problems.append(f"{request.request_id} 待审批但节点下标越界")
        # 部门维度：流水合计 == spent
        per_dept = {}
        for entry in ledger:
            per_dept[entry.dept_id] = per_dept.get(entry.dept_id, 0) + entry.amount_cents
        for dept_id, total in per_dept.items():
            if self._repo.get_budget(dept_id).spent_cents != total:
                problems.append(f"部门 {dept_id} 流水合计 {total} 与已用预算 {self._repo.get_budget(dept_id).spent_cents} 不一致")
        return problems
