Command: cat > proj/approval_demo/repository.py <<'PYEOF'
"""存储抽象与内存实现。

关键点：引擎只依赖 Repository 协议，不关心底层是不是数据库；
换成 SQLite / MySQL 只需要另写一个实现，核心规则与状态机零改动。
"""

from typing import Dict, List, Optional, Protocol

from .errors import BudgetInsufficient, NotFoundError
from .model import ApprovalAction, Budget, Decision, LedgerEntry, Request


class Repository(Protocol):
    """引擎需要的最小存储能力。"""

    def save_request(self, request: Request) -> None:
        """按 request_id 落库（覆盖式保存，版本号由引擎维护）。"""

    def get_request(self, request_id: str) -> Optional[Request]:
        """按申请单号取单。"""

    def find_by_submit_id(self, submit_id: str) -> Optional[Request]:
        """按提交编号取单，用于幂等判断。"""

    def add_action(self, action: ApprovalAction) -> None:
        """追加审批动作流水。"""

    def actions(self, request_id: str) -> List[ApprovalAction]:
        """取某单的动作流水。"""

    def add_decision(self, decision: Decision) -> None:
        """追加规则判定记录。"""

    def decisions(self, request_id: str) -> List[Decision]:
        """取某单的判定记录。"""

    def get_budget(self, dept_id: str) -> Budget:
        """取部门预算。"""

    def has_debit(self, request_id: str) -> bool:
        """该单是否已经扣减过预算。"""

    def debit(self, dept_id: str, amount_cents: int, request_id: str, at: str) -> LedgerEntry:
        """扣减预算并记一条流水；余额不足或重复扣减会抛错。"""

    def ledger(self, request_id: Optional[str] = None) -> List[LedgerEntry]:
        """取预算流水，可按单号过滤。"""


class InMemoryRepository:
    """内存实现：够用于演示与测试，也是"核心逻辑不依赖数据库"的证明。"""

    def __init__(self, budgets: Optional[Dict[str, Budget]] = None):
        self._requests: Dict[str, Request] = {}
        self._by_submit_id: Dict[str, str] = {}
        self._actions: Dict[str, List[ApprovalAction]] = {}
        self._decisions: Dict[str, List[Decision]] = {}
        self._budgets: Dict[str, Budget] = dict(budgets or {})
        self._ledger: List[LedgerEntry] = []

    # ---- 申请单 ----
    def save_request(self, request: Request) -> None:
        existing = self._requests.get(request.request_id)
        if existing is not None and existing.version == request.version and existing != request:
            raise ValueError(
                f"版本冲突：{request.request_id} 已存在 version={request.version} 的不同内容"
            )
        self._requests[request.request_id] = request
        self._by_submit_id[request.submit_id] = request.request_id

    def get_request(self, request_id: str) -> Optional[Request]:
        return self._requests.get(request_id)

    def find_by_submit_id(self, submit_id: str) -> Optional[Request]:
        request_id = self._by_submit_id.get(submit_id)
        return self._requests.get(request_id) if request_id else None

    # ---- 流水 ----
    def add_action(self, action: ApprovalAction) -> None:
        self._actions.setdefault(action.request_id, []).append(action)

    def actions(self, request_id: str) -> List[ApprovalAction]:
        return list(self._actions.get(request_id, ()))

    def add_decision(self, decision: Decision) -> None:
        self._decisions.setdefault(decision.request_id, []).append(decision)

    def decisions(self, request_id: str) -> List[Decision]:
        return list(self._decisions.get(request_id, ()))

    # ---- 预算 ----
    def get_budget(self, dept_id: str) -> Budget:
        budget = self._budgets.get(dept_id)
        if budget is None:
            raise NotFoundError(f"部门 {dept_id} 没有预算账户")
        return budget

    def has_debit(self, request_id: str) -> bool:
        return any(entry.request_id == request_id for entry in self._ledger)

    def debit(self, dept_id: str, amount_cents: int, request_id: str, at: str) -> LedgerEntry:
        if self.has_debit(request_id):
            raise ValueError(f"{request_id} 已经扣减过预算，禁止重复扣减")
        budget = self.get_budget(dept_id)
        if budget.available_cents < amount_cents:
            raise BudgetInsufficient(
                f"部门 {dept_id} 可用 {budget.available_cents} 分，"
                f"申请 {amount_cents} 分，预算不足"
            )
        updated = Budget(
            dept_id=dept_id,
            total_cents=budget.total_cents,
            spent_cents=budget.spent_cents + amount_cents,
        )
        self._budgets[dept_id] = updated
        entry = LedgerEntry(
            request_id=request_id,
            dept_id=dept_id,
            amount_cents=amount_cents,
            balance_after_cents=updated.available_cents,
            at=at,
        )
        self._ledger.append(entry)
        return entry

    def ledger(self, request_id: Optional[str] = None) -> List[LedgerEntry]:
        if request_id is None:
            return list(self._ledger)
        return [entry for entry in self._ledger if entry.request_id == request_id]
